const a=document.querySelector("#api-key"),o=document.querySelector("#key-status"),i=document.querySelector("#groq-key"),n=document.querySelector("#groq-key-status"),l=document.querySelector("#mic-status"),y=document.querySelector("#shortcut"),t=document.querySelector("#transcription-mode"),u=document.querySelector("#transcription-status");async function m(){const e=await chrome.storage.local.get("geminiApiKey");o.textContent=typeof e.geminiApiKey=="string"&&e.geminiApiKey?"A key is saved locally.":"No key configured.";const c=await chrome.commands.getAll();y.textContent=c.find(d=>d.name==="toggle-recording")?.shortcut||"Not assigned";const r=await chrome.storage.local.get("transcriptionMode");t.value=r.transcriptionMode==="local"||r.transcriptionMode==="cloud"?r.transcriptionMode:"auto",u.textContent=t.value==="cloud"?"Audio will be sent to Gemini Transcribe.":t.value==="local"?"Audio stays on this computer.":"Prompt Pilot chooses local or cloud based on device capability.";const s=await chrome.storage.local.get("groqApiKey");n.textContent=typeof s.groqApiKey=="string"&&s.groqApiKey?"A Groq key is saved locally.":"No Groq key configured. Chat context remains unavailable."}document.querySelector("#save-key").addEventListener("click",async()=>{const e=a.value.trim();if(!e){o.textContent="Enter a key first.";return}await chrome.storage.local.set({geminiApiKey:e}),a.value="",o.textContent="Saved locally."});t.addEventListener("change",async()=>{const e=t.value==="local"||t.value==="cloud"?t.value:"auto";await chrome.storage.local.set({transcriptionMode:e}),u.textContent=e==="cloud"?"Audio will be sent to Gemini Transcribe.":e==="local"?"Audio stays on this computer.":"Prompt Pilot chooses local or cloud based on device capability."});document.querySelector("#remove-key").addEventListener("click",async()=>{await chrome.storage.local.remove("geminiApiKey"),a.value="",o.textContent="Key removed."});document.querySelector("#save-groq-key").addEventListener("click",async()=>{const e=i.value.trim();if(!e){n.textContent="Enter a Groq key first.";return}await chrome.storage.local.set({groqApiKey:e}),i.value="",n.textContent="Saved locally."});document.querySelector("#remove-groq-key").addEventListener("click",async()=>{await chrome.storage.local.remove("groqApiKey"),i.value="",n.textContent="Groq key removed."});document.querySelector("#enable-mic").addEventListener("click",async()=>{try{(await navigator.mediaDevices.getUserMedia({audio:!0})).getTracks().forEach(c=>c.stop()),l.textContent="Microphone enabled. You can record from ChatGPT now."}catch{l.textContent="Microphone access was denied. Allow it in Chrome site settings and try again."}});document.querySelector("#change-shortcut").addEventListener("click",()=>{chrome.tabs.create({url:"chrome://extensions/shortcuts"})});m();
